"""Authored control objectives and procedures; Google references explain product behavior.
Assessment criteria and falsification probes are this independent playbook's audit method.
"""
BASE = 'https://docs.cloud.google.com/'
CONTROLS = []
DOMAINS = {}
def domain(code, name, owner, rows):
    DOMAINS[code] = dict(name=name, owner=owner)
    for i, row in enumerate(rows.strip().splitlines(), 1):
        title, procedure, criterion, challenge, evidence, operations, sources = row.split('|')
        CONTROLS.append(dict(id=f'{code}-{i:02}', domain=code, title=title,
            objective=title, owner=owner, priority='Risk-based; set after business-impact review',
            applicability=f'All in-scope uses of {name.lower()}; document approved exclusions and service absence.',
            procedure=procedure, criterion=criterion, falsification=challenge,
            required_evidence=evidence.split(';'), operations=operations.split(),
            sources=[s if s.startswith('https://') else BASE+s for s in sources.split()],
            remediation='Agree a change with the service owner against the failed criterion, assess dependencies and rollback, implement through change control, then obtain independent retest evidence. Collection scripts do not remediate.',
            cadence='At initial engagement and material change; recurring interval follows the approved risk plan.'))

